{"chunk_id": "348ec4", "wall_time_seconds": 0.9570564, "exit_code": 0, "original_token_count": 6632, "output": """"Deterministic evidence admission and ordering. Never a clinical certainty score."""

import hashlib, json, re
from urllib.parse import urlparse
from .schemas import SourceDocument

POLICY_VERSION = "us-evidence-2026-10-27.v1"
RANKING_RULES = [
    {
        "criterion": "Source identity",
        "rule": "Canonical PMID/NCT and exact API origin; unverified identity is excluded.",
    },
    {
        "criterion": "Publication status",
        "rule": "Retracted records excluded; corrections and missing metadata flagged.",
    },
    {
        "criterion": "Question match",
        "rule": "Condition term coverage is an ordering aid; applicability still requires review.",
    },
    {
        "criterion": "Evidence class",
        "rule": "Guideline, synthesis, randomized trial, other study; registries have a separate role.",
    },
    {
        "criterion": "Results and access",
        "rule": "Registry without results supports development only. Abstract-only limitations remain visible.",
    },
    {
        "criterion": "Dates",
        "rule": "Publication/update date breaks ties. Retrieval time never makes a study new.",
    },
    {
        "criterion": "Independent lineage",
        "rule": "Explicit NCT/DOI links identify shared families. Unknown overlap remains unknown.",
    },
]


def digest(data) -> str:
    return hashlib.sha256(json.dumps(data, sort_keys=True, ensure_ascii=False).encode()).hexdigest()


def resolve_pointer(data, pointer: str):
    node = data
    for token in pointer.lstrip("/").split("/"):
        token = token.replace("~1", "/").replace("~0", "~")
        node = node[int(token)] if isinstance(node, list) else node[token]
    return node


def class_info(doc: SourceDocument):
    types = {x.lower() for x in doc.publication_types}
    if doc.source == "clinicaltrials":
        return "Trial registry", 5
    if types & {"practice guideline", "guideline"}:
        return "Guideline publication", 0
    if types & {"meta-analysis", "systematic review"}:
        return "Evidence synthesis", 1
    if "randomized controlled trial" in types:
        return "Randomized trial", 2
    if any("clinical trial" in x for x in types):
        return "Clinical study", 3
    return "Published literature", 4


def identity_ok(doc: SourceDocument) -> bool:
    try:
        parsed = urlparse(doc.url)
        invalid_port = parsed.port is not None
    except ValueError:
        return False
    if not doc.verified or parsed.scheme != "https" or parsed.username or parsed.password or invalid_port:
        return False
    if doc.source == "pubmed":
        return bool(
            re.fullmatch(r"\d{1,10}", doc.canonical_id)
            and parsed.hostname == "pubmed.ncbi.nlm.nih.gov"
            and parsed.path == f"/{doc.canonical_id}/"
        )
    return bool(
        re.fullmatch(r"NCT\d{8}", doc.canonical_id)
        and parsed.hostname == "clinicaltrials.gov"
        and parsed.path == f"/study/{doc.canonical_id}"
    )


def rank_documents(documents: list[SourceDocument], condition: str, run_id: str) -> list[dict]:
    unique = {}
    for doc in documents:
        unique.setdefault((doc.source, doc.canonical_id), doc)
    ranked = []
    terms = set(re.findall(r"\w+", condition.lower())) - {"of", "the", "and", "in"}
    for doc in unique.values():
        reasons = []
        excluded = not identity_ok(doc) or doc.retracted
        if not identity_ok(doc):
            reasons.append("SOURCE_IDENTITY_UNVERIFIED")
        if doc.retracted:
            reasons.append("RETRACTED_PUBLICATION")
        if doc.corrected:
            reasons.append("CORRECTION_REQUIRES_REVIEW")
        if doc.access_level == "abstract_only":
            reasons.append("ABSTRACT_ONLY")
        if not doc.published_date:
            reasons.append("PUBLICATION_DATE_UNKNOWN")
        if doc.source == "clinicaltrials" and not doc.has_results:
            reasons.append("REGISTRY_WITHOUT_RESULTS")
        if doc.jurisdiction != "US":
            reasons.append("US_APPLICABILITY_NOT_VERIFIED")
        evidence_class, priority = class_info(doc)
        snapshot_hash = digest(doc.snapshot)
        cid = "cit_" + digest([run_id, doc.source, doc.canonical_id])[:24]
        passages = []
        for passage in doc.passages:
            try:
                value = resolve_pointer(doc.snapshot, passage["locator"])
                if not isinstance(value, str) or value != passage["text"] or not value.strip():
                    continue
                passages.append(
                    {
                        "id": "ev_" + digest([cid, passage["locator"], snapshot_hash])[:30],
                        "citation_id": cid,
                        "locator": passage["locator"],
                        "text": value,
                        "content_hash": digest(value),
                    }
                )
            except (KeyError, ValueError, IndexError, TypeError):
                continue
        if not passages:
            reasons.append("NO_INSPECTABLE_PASSAGE")
        corpus = (doc.title + " " + " ".join(x["text"] for x in passages)).lower()
        relevance = sum(term in corpus for term in terms)
        if terms and relevance == 0:
            excluded = True
            reasons.append("CONDITION_MISMATCH")
        family = (
            ("nct:" + doc.nct_ids[0])
            if len(doc.nct_ids) == 1
            else ("doi:" + doc.doi.lower() if doc.doi else f"{doc.source}:{doc.canonical_id}")
        )
        basis = (
            "explicit_trial_identifier"
            if len(doc.nct_ids) == 1
            else "same_publication_only; underlying study overlap unknown"
        )
        allowed = (
            ["published_finding"]
            if doc.source == "pubmed" and passages
            else ["development", "organization"]
            if doc.source == "clinicaltrials" and passages
            else []
        )
        if doc.has_results and passages:
            allowed.append("efficacy")
        if excluded:
            allowed = []
        status = "excluded" if excluded else "limited"
        date_number = int(
            re.sub(r"\D", "", (doc.updated_date or doc.published_date or "0000")[:10]).ljust(8, "0")[:8]
        )
        order = [int(excluded), -relevance, priority, -int(doc.has_results), -date_number, doc.canonical_id]
        ranked.append(
            {
                **doc.model_dump(exclude={"snapshot", "passages"}),
                "id": cid,
                "snapshot_id": f"{doc.source}:{doc.canonical_id}:{snapshot_hash[:24]}",
                "snapshot_hash": snapshot_hash,
                "snapshot": doc.snapshot,
                "is_synthetic": bool(doc.snapshot.get("synthetic")),
                "evidence": passages,
                "evidence_class": evidence_class,
                "class_priority": priority,
                "relevance_terms_matched": relevance,
                "relevance_terms_total": len(terms),
                "family_id": family,
                "family_basis": basis,
                "allowed_claim_types": allowed,
                "decision": status,
                "reason_codes": reasons,
                "policy_version": POLICY_VERSION,
                "ordering": order,
            }
        )
    ranked.sort(key=lambda x: tuple(x["ordering"]))
    families = {}
    for i, item in enumerate(ranked, 1):
        item["rank"] = i
        item["family_count"] = sum(x["family_id"] == item["family_id"] for x in ranked)
        item["duplicate_of"] = families.get(item["family_id"])
        families.setdefault(item["family_id"], item["id"])
    return ranked


def validate_claim(candidate: dict, citations: list[dict]) -> tuple[bool, list[str], list[dict]]:
    reasons = []
    refs = []
    by_evidence = {e["id"]: (c, e) for c in citations for e in c["evidence"]}
    if candidate["claim_type"] in {"current_care", "approval"}:
        reasons.append("REGISTERED_GUIDELINE_OR_REGULATORY_EVIDENCE_REQUIRED")
    if re.search(
        r"\b(?:FDA[- ]approved|standard of care|recommended first[- ]line)\b", candidate["text"], re.I
    ):
        reasons.append("UNVERIFIED_REGULATORY_OR_CARE_LANGUAGE")
    if re.search(r"\b(?:you should|patients should|prescribe|start taking)\b", candidate["text"], re.I):
        reasons.append("PATIENT_RECOMMENDATION_OUT_OF_SCOPE")
    for ref in candidate["references"]:
        pair = by_evidence.get(ref["evidence_id"])
        if not pair:
            reasons.append("UNKNOWN_EVIDENCE_ID")
            continue
        citation, evidence = pair
        if citation["decision"] == "excluded":
            reasons.append("EXCLUDED_SOURCE")
        if candidate["claim_type"] not in citation["allowed_claim_types"]:
            reasons.append("CLAIM_TYPE_NOT_PERMITTED")
        if ref["quote"] not in evidence["text"]:
            reasons.append("QUOTE_NOT_IN_SNAPSHOT")
        refs.append(
            {
                **ref,
                "citation_id": citation["id"],
                "locator": evidence["locator"],
                "snapshot_hash": citation["snapshot_hash"],
            }
        )
    if not refs:
        reasons.append("NO_VALID_REFERENCE")
    return not reasons, list(dict.fromkeys(reasons)), refs


def find_conflicts(claims: list[dict], citations: list[dict]) -> list[dict]:
    """Potential opposite findings only when intervention/population/outcome explicitly match."""
    conflicts = []
    family = {c["id"]: c["family_id"] for c in citations}

    def normalize(s):
        return " ".join(re.findall(r"\w+", s.lower()))

    for i, a in enumerate(claims):
        for b in claims[i + 1 :]:
            key_a = tuple(normalize(a.get(k, "")) for k in ["intervention", "population", "outcome"])
            key_b = tuple(normalize(b.get(k, "")) for k in ["intervention", "population", "outcome"])
            if (
                not all(key_a)
                or any(x in {"unknown", "not specified", "unspecified"} for x in key_a)
                or key_a != key_b
            ):
                continue
            if {a["direction"], b["direction"]} != {"positive", "negative"}:
                continue
            a_f = {family[r["citation_id"]] for r in a["references"]}
            b_f = {family[r["citation_id"]] for r in b["references"]}
            conflicts.append(
                {
                    "id": "conf_" + digest([a["id"], b["id"]])[:24],
                    "claim_ids": [a["id"], b["id"]],
                    "citation_ids": list(
                        dict.fromkeys([r["citation_id"] for r in a["references"] + b["references"]])
                    ),
                    "type": "within_study_disagreement" if a_f & b_f else "potential_opposing_findings",
                    "summary": f"Opposite extracted findings for {a['intervention']} / {a['outcome']}. Both accounts are preserved; no winner is selected.",
                    "resolution": "Analyst review required: compare population, comparator, endpoint, follow-up and source dates.",
                    "status": "unresolved",
                    "review_needed": True,
                }
            )
    return conflicts
import asyncio
from sqlalchemy.dialects.postgresql import insert
from .config import get_settings
from .database import (
    Session,
    ResearchRun,
    Citation,
    SourceSnapshot,
    EvidencePassage,
    ClaimRecord,
    ClaimEvidence,
    ConflictRecord,
    event,
)
from .fixtures import fixture_documents
from .llm import EvidenceModel, ModelUnavailable
from .policy import rank_documents, validate_claim, find_conflicts, digest, POLICY_VERSION
from .schemas import ResearchRequest, ProcessRequest, utcnow
from .sources import Sources


def structured_claims(citations: list[dict]) -> list[dict]:
    """Copy traceable trial fields; no model or medical inference."""
    claims = []
    for c in citations:
        if c["source"] != "clinicaltrials" or c["decision"] == "excluded":
            continue
        by_pointer = {e["locator"]: e for e in c["evidence"]}
        title = by_pointer.get("/protocolSection/identificationModule/briefTitle")
        status = by_pointer.get("/protocolSection/statusModule/overallStatus")
        if title:
            refs = [{"evidence_id": e["id"], "quote": e["text"]} for e in [title, status] if e]
            claims.append(
                {
                    "section": "emerging",
                    "claim_type": "development",
                    "text": f"Registered study: {title['text']}"
                    + (f". Registry status: {status['text']}." if status else "."),
                    "intervention": "unknown",
                    "population": "unknown",
                    "outcome": "registry status",
                    "direction": "neutral",
                    "references": refs,
                    "origin": "structured_source_fields",
                }
            )
        for role in c["organization_roles"]:
            e = by_pointer.get(role["locator"])
            if e:
                claims.append(
                    {
                        "section": "organizations",
                        "claim_type": "organization",
                        "text": f"{role['name']} is listed as {role['role'].replace('_', ' ')} for {c['canonical_id']}.",
                        "intervention": "unknown",
                        "population": "unknown",
                        "outcome": "documented organization role",
                        "direction": "neutral",
                        "references": [{"evidence_id": e["id"], "quote": e["text"]}],
                        "origin": "structured_source_fields",
                    }
                )
    return claims[:18]


def fixture_claims(citations: list[dict]) -> list[dict]:
    return [
        {
            "section": "care_landscape",
            "claim_type": "published_finding",
            "text": c["evidence"][0]["text"],
            "intervention": "Example intervention",
            "population": "adults",
            "outcome": "example endpoint",
            "direction": "positive" if i == 0 else "negative",
            "references": [{"evidence_id": c["evidence"][0]["id"], "quote": c["evidence"][0]["text"]}],
            "origin": "synthetic_policy_fixture",
        }
        for i, c in enumerate(citations)
    ]


def store_result(run_id: str, result: dict, citations: list[dict]):
    with Session.begin() as db:
        for c in citations:
            db.execute(
                insert(SourceSnapshot)
                .values(
                    id=c["snapshot_id"],
                    source=c["source"],
                    canonical_id=c["canonical_id"],
                    content_hash=c["snapshot_hash"],
                    data=c["snapshot"],
                )
                .on_conflict_do_nothing(index_elements=[SourceSnapshot.id])
            )
            db.add(
                Citation(
                    id=c["id"],
                    run_id=run_id,
                    snapshot_id=c["snapshot_id"],
                    data={k: v for k, v in c.items() if k != "snapshot"},
                )
            )
            db.flush()
            for e in c["evidence"]:
                db.add(
                    EvidencePassage(
                        id=e["id"],
                        citation_id=c["id"],
                        snapshot_id=c["snapshot_id"],
                        locator=e["locator"],
                        text=e["text"],
                    )
                )
        db.flush()
        for claim in result["claims"]:
            db.add(ClaimRecord(id=claim["id"], run_id=run_id, data=claim))
            db.flush()
            for ref in {r["evidence_id"]: r for r in claim["references"]}.values():
                db.add(
                    ClaimEvidence(
                        claim_id=claim["id"],
                        evidence_id=ref["evidence_id"],
                        quote=ref["quote"],
                        check={
                            "quote_in_snapshot": True,
                            "support_check": claim["support_check"],
                            "snapshot_hash": ref["snapshot_hash"],
                        },
                    )
                )
        for conflict in result["conflicts"]:
            db.add(ConflictRecord(id=conflict["id"], run_id=run_id, data=conflict))
        run = db.get(ResearchRun, run_id)
        run.result = result
        run.status = result["status"]
        run.finished_at = utcnow()


async def execute(run_id: str, request: ResearchRequest, sources: Sources):
    with Session.begin() as db:
        db.get(ResearchRun, run_id).status = "running"
    citations = []
    claims = []
    excluded_claims = []
    attempts = []
    warnings = []
    model = EvidenceModel()
    error = False
    try:
        async with asyncio.timeout(get_settings().run_timeout_seconds):
            event(
                run_id, "retrieving", "Retrieving fixed-source records; source text cannot change the policy."
            )
            if request.mode == "fixture":
                documents = fixture_documents(request.condition)
                attempts = [
                    {
                        "source": "synthetic_fixture",
                        "status": "success",
                        "reason": "Fabricated edge-case evidence; never a live result.",
                    }
                ]
            else:
                documents, attempts = await sources.collect(
                    request.condition,
                    min(request.max_records, get_settings().max_records),
                    getattr(request, "pmids", None) if isinstance(request, ProcessRequest) else None,
                    getattr(request, "nct_ids", None) if isinstance(request, ProcessRequest) else None,
                )
            event(
                run_id,
                "authenticating",
                "Checking canonical source identity, snapshot locators and publication status.",
            )
            citations = rank_documents(documents, request.condition, run_id)
            event(
                run_id,
                "ranking",
                "Applying the fixed ordering policy and grouping explicit study identifiers.",
            )
            candidates = (
                fixture_claims(citations) if request.mode == "fixture" else structured_claims(citations)
            )
            model_candidates = []
            if request.use_llm and request.mode == "live":
                event(
                    run_id,
                    "extracting",
                    "OpenAI reads selected saved evidence through one allowlisted function tool.",
                )
                try:
                    extraction = await model.extract(request.condition, citations)
                    warnings.extend(extraction.limitations)
                    for candidate in extraction.claims:
                        raw = candidate.model_dump()
                        ok, reasons, refs = validate_claim(raw, citations)
                        if ok:
                            model_candidates.append(
                                {**raw, "references": refs, "origin": "openai_extraction"}
                            )
                        else:
                            excluded_claims.append({"text": raw["text"], "reason_codes": reasons})
                    event(
                        run_id,
                        "validating",
                        "Checking exact quotations and reviewing semantic support; automated review is not clinical validation.",
                    )
                    review = await model.review(model_candidates, citations)
                    for i, candidate in enumerate(model_candidates):
                        decision = review.get(i)
                        if decision and decision["supported"]:
                            candidate["support_explanation"] = decision["explanation"]
                            candidates.append(candidate)
                        else:
                            excluded_claims.append(
                                {
                                    "text": candidate["text"],
                                    "reason_codes": ["SEMANTIC_SUPPORT_NOT_CONFIRMED"],
                                    "explanation": decision["explanation"]
                                    if decision
                                    else "No valid reviewer decision.",
                                }
                            )
                except ModelUnavailable as exc:
                    warnings.append(
                        exc.code
                        + ": generated synthesis is unavailable; inspect source evidence and structured registry fields."
                    )
            elif request.mode == "live":
                warnings.append(
                    "Model synthesis was disabled. Literature is presented as source evidence, without generated medical conclusions."
                )
            for candidate in candidates:
                ok, reasons, refs = validate_claim(candidate, citations)
                if not ok:
                    excluded_claims.append({"text": candidate["text"], "reason_codes": reasons})
                    continue
                candidate["references"] = refs
                candidate["id"] = "cl_" + digest([run_id, candidate["text"], refs])[:26]
                candidate["support_check"] = (
                    "synthetic_fixture"
                    if request.mode == "fixture"
                    else "structured_field_copy"
                    if candidate["origin"] == "structured_source_fields"
                    else "automated_semantic_review"
                )
                candidate["review_needed"] = candidate["origin"] != "structured_source_fields"
                if not any(c["text"] == candidate["text"] for c in claims):
                    claims.append(candidate)
    except TimeoutError:
        warnings.append("RUN_DEADLINE_REACHED: only completed evidence stages are shown.")
    except asyncio.CancelledError:
        with Session.begin() as db:
            run = db.get(ResearchRun, run_id)
            run.status = "interrupted"
            run.finished_at = utcnow()
        raise
    except Exception:
        warnings.append("PROCESSING_ERROR: the run could not finish all evidence stages.")
        error = True
    conflicts = find_conflicts(claims, citations)
    warnings.insert(
        0,
        "No registered, currency-checked US guideline was retrieved. Current standard of care is not established by this literature search.",
    )
    if request.mode == "fixture":
        warnings.insert(
            0,
            "SYNTHETIC FIXTURE: all publications and findings in this run are fabricated to demonstrate policy behavior.",
        )
    if any(c["access_level"] == "abstract_only" for c in citations):
        warnings.append("PubMed evidence is abstract-only where available; full papers were not read.")
    if any(a.get("truncated") for a in attempts):
        warnings.append(
            "Result caps were reached. This is a bounded search, not a comprehensive evidence review."
        )
    if any(a["status"] == "failed" for a in attempts):
        warnings.append(
            "One or more sources failed. No-match and retrieval failure are not evidence of absence."
        )
    result = {
        "run_id": run_id,
        "condition": request.condition,
        "jurisdiction": "US",
        "mode": request.mode,
        "status": "failed" if error and not citations else "partial" if citations else "failed",
        "policy_version": POLICY_VERSION,
        "as_of": utcnow().isoformat(),
        "model": get_settings().model_name() if model.usage else None,
        "source_attempts": attempts,
        "citations": [{k: v for k, v in c.items() if k != "snapshot"} for c in citations],
        "claims": claims,
        "excluded_claims": excluded_claims,
        "conflicts": conflicts,
        "coverage": {
            "current_care": {
                "status": "unavailable",
                "reason": "Applicable current US guideline required; generic PubMed indexing is insufficient.",
            },
            "care_landscape": {
                "status": "limited" if any(c["source"] == "pubmed" for c in citations) else "unavailable",
                "reason": "Bounded literature search; abstract access and study applicability require review.",
            },
            "emerging": {
                "status": "limited"
                if any(c["source"] == "clinicaltrials" for c in citations)
                else "unavailable",
                "reason": "Registered development activity; registry listing is not approval or benefit.",
            },
            "organizations": {
                "status": "limited" if any(c["organization_roles"] for c in citations) else "unavailable",
                "reason": "Documented sponsor/collaborator roles only.",
            },
        },
        "warnings": list(dict.fromkeys(warnings)),
        "usage": {
            "model_requests": len(model.usage),
            "requests": model.usage,
            "tool_calls": model.tool_calls,
            "cost_usd": None,
        },
        "ranking_explanation": "Ordering: source admission, condition-term match, evidence class, results availability, source date, stable identifier. This is research priority, not clinical certainty or treatment suitability.",
    }
    store_result(run_id, result, citations)
    event(
        run_id,
        result["status"],
        f"Saved {len(citations)} citations, {len(claims)} supported/structured claims and {len(conflicts)} potential conflicts.",
    )
    return result
"}

