tasks: set[asyncio.Task] = set()


@asynccontextmanager
async def lifespan(app):
    initialize()
    app.state.sources = Sources()
    try:
        yield
    finally:
        for task in tasks:
            task.cancel()
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)
        await app.state.sources.close()


